with unpacked as (select id, created_at, items, ship_to, array_contains(coupon_codes, 'BUNDLE') as used_bundle, array_join(array_sort(coupon_codes), ',') as coupons_text, exists(items, i -> i.price > 100) as has_premium_item from carts) select id, coupons_text, row_number() over w_recent row_seq, row_number() over w_recent row_seq_2 from unpacked window w_recent as (order by created_at, id);
